BEGIN;
CREATE TABLE public.selling_categories (
 id text PRIMARY KEY CHECK (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(id) BETWEEN 2 AND 60),
 name text NOT NULL CHECK (char_length(btrim(name)) BETWEEN 2 AND 80),
 description text NOT NULL CHECK (char_length(btrim(description)) BETWEEN 10 AND 600),
 image_url text NOT NULL CHECK (char_length(image_url) BETWEEN 1 AND 2000),
 tagline text NOT NULL DEFAULT '' CHECK (char_length(tagline) <= 100),
 accent_color text NOT NULL DEFAULT '#e3efff' CHECK (accent_color ~ '^#[0-9a-fA-F]{6}$'),
 types text[] NOT NULL CHECK (cardinality(types) BETWEEN 1 AND 50),
 preparation text NOT NULL CHECK (char_length(btrim(preparation)) BETWEEN 10 AND 2000),
 intro text NOT NULL DEFAULT '' CHECK (char_length(intro) <= 2000),
 seo_title text NOT NULL DEFAULT '' CHECK (char_length(seo_title) <= 120),
 seo_description text NOT NULL DEFAULT '' CHECK (char_length(seo_description) <= 300),
 sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order BETWEEN 0 AND 9999),
 is_active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.selling_categories ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.selling_categories TO anon, authenticated;
GRANT INSERT, UPDATE ON public.selling_categories TO authenticated;
GRANT ALL ON public.selling_categories TO service_role;
CREATE POLICY "Public reads published selling categories" ON public.selling_categories FOR SELECT TO anon,authenticated USING (is_active);
CREATE POLICY "Admins read hidden selling categories" ON public.selling_categories FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins create selling categories" ON public.selling_categories FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update selling categories" ON public.selling_categories FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.keep_selling_category_slug() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id <> OLD.id THEN RAISE EXCEPTION 'Category URL cannot be changed; hide the old category and create a new one'; END IF; NEW.updated_at := now(); RETURN NEW; END; $$;
CREATE TRIGGER selling_category_updated BEFORE UPDATE ON public.selling_categories FOR EACH ROW EXECUTE FUNCTION public.keep_selling_category_slug();
INSERT INTO public.selling_categories(id,name,description,image_url,tagline,accent_color,types,preparation,intro,seo_title,seo_description,sort_order) VALUES
('toys','Toys & games','Wooden toys, puzzles, building sets and games.','/sell-categories/toys.webp','A whole new playtime','#fff0cf',ARRAY['Building blocks','Puzzles & board games','Soft toys & dolls','Learning toys','Toy sets & bundles','Wooden toys','Action figures','Toy cars & trains','Pretend-play sets','Dollhouses & playsets','Musical toys','Stacking & sorting toys'],'Clean toys, check for loose parts and mention any missing pieces.','From a toy box full of building blocks to a board game your child has mastered, useful toys can have plenty of playtime left. Share individual toys or a related collection, describe the condition and let our team review the next steps.','Sell Used Toys & Games in Bangalore | Zapiboo','Sell pre-loved toys, puzzles, building blocks and games in Bangalore. Explore accepted types, bundle tips, condition checks and pickup next steps.',0),
('books','Kids books','Picture books, story collections and activity books.','/sell-categories/books.webp','Stories worth sharing','#e3efff',ARRAY['Picture books','Story books','Learning & activity books','Book sets & bundles','Board books','Early readers','Phonics books','Alphabet & number books','Comics & graphic novels','Kids encyclopedias','Chapter books','School reading books'],'Check for torn pages, writing and missing covers. Group sets together.','Finished picture books, early readers and chapter-book collections can make room for a new reading stage. Tell us the titles or type of books, whether the collection is complete and how much wear the books have.','Sell Used Kids Books in Bangalore | Zapiboo','Sell picture books, story books, early readers and kids book bundles in Bangalore. Check book condition, bundle ideas and pickup details.',10),
('clothing','Kids clothing','Outgrown clothes, shoes and accessories.','/sell-categories/clothing.webp','Outgrown, not out of style','#ffe7ed',ARRAY['Baby clothing','Kids clothing','Shoes','Accessories','Clothing bundles','T-shirts & tops','Dresses & skirts','Trousers & shorts','Sweaters & jackets','Baby sleepsuits','Party & occasion wear','Raincoats & winterwear'],'Wash and dry clothing. Include the size and mention stains or wear.','Outgrown outfits do not always mean worn-out clothes. Share baby clothing, everyday outfits, occasion wear or shoes with clear size and condition notes, so our team can understand the collection before handover.','Sell Used Kids Clothes & Shoes in Bangalore | Zapiboo','Sell outgrown baby clothes, kids clothing, shoes and clothing bundles in Bangalore. See condition tips, size details and pickup next steps.',20),
('gear','Baby gear','Strollers, high chairs, cots and other baby essentials.','/sell-categories/gear.webp','Big help for little ones','#e0f6ef',ARRAY['Strollers','High chairs','Cots & cribs','Car seats','Other baby gear','Prams','Travel cots','Booster seats','Baby carriers','Playpens','Baby bouncers','Baby changing tables'],'Check straps, locks and moving parts. Mention damage, recalls or missing accessories. For car seats, include expiry and accident history.','A stroller, high chair or cot can take up a lot of room after your family moves to the next stage. Share the item details, included accessories and condition so our team can review larger baby gear before discussing collection.','Sell Used Baby Gear & Strollers in Bangalore | Zapiboo','Share pre-loved strollers, high chairs, cots and baby gear in Bangalore. See the details to include, accessory checks and pickup preparation.',30),
('cycles','Cycles & ride-ons','Balance bikes, kids cycles, tricycles and ride-ons.','/sell-categories/cycles.webp','Ready for the next adventure','#e3f4ff',ARRAY['Balance bikes','Kids bicycles','Tricycles','Scooters & ride-ons','Training-wheel bicycles','Kick scooters','Ride-on cars','Pedal cars','Push-along ride-ons','Battery-powered ride-ons','Ride-on motorbikes','Bicycle accessories'],'Check the brakes, tyres and frame. Include wheel size and any repair needs.','When the next growth spurt calls for a bigger bike, an outgrown cycle or ride-on may be ready for another adventure. Include the type, wheel size if known and an honest description of how it works.','Sell Used Kids Cycles & Ride-ons in Bangalore | Zapiboo','Sell outgrown kids bicycles, balance bikes, tricycles and ride-ons in Bangalore. Share condition, size, accessories and pickup details.',40),
('electronics','Kids electronics','Learning tablets, electronic toys and STEM kits.','/sell-categories/electronics.webp','Little minds, big discoveries','#fff0cf',ARRAY['Learning tablets','Electronic learning toys','STEM kits','Other kids electronics','Kids learning laptops','Coding & robotics kits','Electronic story readers','Talking alphabet toys','Math learning devices','Electronic keyboards','Kids digital cameras','Science experiment kits'],'Check that it works, remove personal accounts and include chargers or accessories.','Learning tablets, coding kits and electronic toys can be useful beyond one stage of childhood. Tell us what the device does, whether it works and which cables, parts or instructions are included.','Sell Used Kids Electronics & STEM Kits in Bangalore | Zapiboo','Share learning tablets, kids laptops, electronic toys and STEM kits in Bangalore. Check working condition, accessories and personal-data preparation.',50);
ALTER TABLE public.leads ADD COLUMN selling_category_id text REFERENCES public.selling_categories(id) ON UPDATE RESTRICT ON DELETE RESTRICT;
CREATE INDEX leads_selling_category_idx ON public.leads(selling_category_id);
CREATE OR REPLACE FUNCTION public.check_pickup_selling_category() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE category_name text; BEGIN IF NEW.selling_category_id IS NOT NULL THEN SELECT name INTO category_name FROM public.selling_categories WHERE id=NEW.selling_category_id AND is_active; IF NOT FOUND THEN RAISE EXCEPTION 'This category is not currently available for pickup'; END IF; NEW.lead_type:='kids_pickup'; NEW.vehicle_type:=category_name; END IF; RETURN NEW; END; $$;
CREATE TRIGGER check_pickup_selling_category BEFORE INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.check_pickup_selling_category();
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('category-images','category-images',true,2097152,ARRAY['image/webp']) ON CONFLICT(id) DO NOTHING;
CREATE POLICY "Public reads category images" ON storage.objects FOR SELECT TO public USING(bucket_id='category-images');
CREATE POLICY "Admins upload category images" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='category-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins remove category images" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='category-images' AND public.has_role(auth.uid(),'admin'));
NOTIFY pgrst,'reload schema';
COMMIT;
